import React, { useState } from "react";
import { createRoot } from "react-dom/client";
import { flushSync } from "react-dom";
import i18next from "i18next";
import { I18nextProvider } from "react-i18next";
import { DelegationHistoryDialog } from "../../src/features/delegations/DelegationHistoryDialog";
import { api } from "../../src/lib/api";
import { useAppStore } from "../../src/stores/app-store";
import "../../src/styles/tokens.css";
import "../../src/styles/ui-kit.css";

await i18next.init({ lng: "en", initImmediate: false, resources: { en: { translation: {} } } });
const pending = { requestId: "approval-a", sessionId: "source-a", revision: 2, status: "pending", expiresAt: new Date(Date.now() + 3600000).toISOString(), projectTitle: "Project A", sessionTitle: "Session A", agentName: "Reviewer", task: "Task", candidate: { providerId: "demo", modelId: "model", priority: 1, approval: "ask" }, candidates: [] };
let requests = [pending], mode = "normal", failNavigation = false;
let resolveFirst;
const calls = [], navigation = [], events = new Set();
const first = new Promise((resolve) => { resolveFirst = resolve; });
const entry = (id, status, project) => ({ id, sessionId: `source-${id}`, sessionTitle: `Session ${id}`, projectTitle: project, delegationId: id, messageId: id, agentName: `Agent ${id}`, description: `Description ${id}`, status, createdAt: "2026-01-01T00:00:00Z", task: "Full task\nEND", report: "Full report\nEND", reportTruncated: true });
const a = entry("a", "running", "Project A"), b = entry("b", "completed", "Project B");
api.listDelegationApprovals = async () => ({ requests });
api.onDelegationApprovalChanged = () => () => {};
api.onAgentEvent = (listener) => { events.add(listener); return () => events.delete(listener); };
api.listDelegationHistory = (query) => { calls.push(query); if (calls.length === 1) return first; if (mode === "error") return Promise.reject(new Error("Fixture history failure")); if (mode === "empty") return Promise.resolve({ entries: [], nextOffset: query.offset === 0 ? 30 : null }); if (query.status === "ended") return Promise.resolve({ entries: [b], nextOffset: null }); if (query.offset === 30) return Promise.resolve({ entries: [b], nextOffset: null }); return Promise.resolve({ entries: [a], nextOffset: 30 }); };
useAppStore.setState({ selectSession: async (id) => { if (failNavigation) throw new Error("Fixture deleted source"); navigation.push(id); useAppStore.setState({ activeSessionId: id }); } });
let target;
window.addEventListener("pi-desktop:notification-target", (event) => { target = event.detail; });
function Harness() { const [open, setOpen] = useState(false); return <><button id="open" onClick={() => setOpen(true)}>Open</button>{open && <DelegationHistoryDialog onClose={() => setOpen(false)} />}</>; }
const root = createRoot(document.getElementById("root"));
flushSync(() => root.render(<I18nextProvider i18n={i18next}><Harness /></I18nextProvider>));
const check = (value, message) => { if (!value) throw Error(message); };
const tick = () => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
const click = (selector) => { const node = document.querySelector(selector); check(node, `Missing ${selector}`); flushSync(() => node.click()); return node; };
const button = (text) => [...document.querySelectorAll(".delegation-history button")].find((node) => node.textContent === text);
const press = (text) => { const node = button(text); check(node, `Missing button ${text}`); flushSync(() => node.click()); };
window.historyProbe = async () => {
  document.getElementById("open").focus(); click("#open"); await tick();
  check(calls[0].status === "all" && !calls[0].projectPath, "Initial query must be global");
  press("delegationHistory.filters.ended"); await tick();
  resolveFirst({ entries: [a], nextOffset: 30 }); await tick();
  check(document.documentElement.textContent.includes("Project B") && !document.documentElement.textContent.includes("Agent a"), "Stale query must not replace ended filter");
  click('[data-delegation-id="b"]'); await tick();
  check(navigation.length === 0 && document.documentElement.textContent.includes("Full task") && document.documentElement.textContent.includes("delegationHistory.truncated"), "Detail must preserve text without navigation");
  press("delegationHistory.back"); await tick();
  check(document.activeElement?.dataset.delegationId === "b", "Back restores row focus");
  press("delegationHistory.filters.all"); await tick(); press("delegationHistory.loadMore"); await tick();
  check(document.documentElement.textContent.includes("Project A") && document.documentElement.textContent.includes("Project B"), "Pagination includes multiple projects");
  let refresh;
  const setTimeout = window.setTimeout;
  window.setTimeout = (callback, delay, ...args) => delay === 500 ? (refresh = callback, 0) : setTimeout(callback, delay, ...args);
  try { for (const listener of events) listener({ event: { type: "tool_end" } }); check(refresh, "Terminal event schedules refresh"); refresh(); }
  finally { window.setTimeout = setTimeout; }
  await tick();
  check(button("delegationHistory.loadMore") && !document.querySelector('[data-delegation-id="b"]'), "Live refresh replaces old page and renews cursor");
  press("delegationHistory.loadMore"); await tick();
  click('[data-delegation-id="b"]'); await tick(); failNavigation = true; press("delegationHistory.openSource"); await tick();
  check(document.querySelector('[role="alert"]')?.textContent.includes("delegationHistory.navigationFailed") && navigation.length === 0, "Deleted source fails visibly without dismissing details");
  failNavigation = false; press("delegationHistory.openSource"); await tick();
  check(navigation.join() === "source-b" && !document.querySelector('[role="dialog"]'), "Only explicit source navigates");
  click("#open"); await tick(); press("delegationHistory.viewApproval"); await tick();
  check(target?.sessionId === "source-a" && target?.requestId === "approval-a" && target?.revision === 2 && navigation.length === 1, "Approval targets exact request without navigation");
  mode = "error"; click("#open"); await tick();
  check(document.querySelector('[role="alert"]'), "History read failure is visible");
  mode = "normal"; press("delegationHistory.retry"); await tick();
  check(document.querySelector('[data-delegation-id="a"]') && !document.querySelector('[role="alert"]'), "Retry restores history");
  click(".delegation-history-header button"); await tick();
  requests = []; mode = "empty"; document.getElementById("open").focus(); click("#open"); await tick();
  const dialog = document.querySelector('[role="dialog"]'); check(dialog && events.size === 1, "Open dialog subscribes once");
  check(document.documentElement.textContent.includes("delegationHistory.noPending") && button("delegationHistory.loadMore") && !document.documentElement.textContent.includes("delegationHistory.empty"), "Empty page with cursor is not end of history");
  press("delegationHistory.loadMore"); await tick(); check(document.documentElement.textContent.includes("delegationHistory.empty"), "Final empty page is definitive");
  dialog.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); await tick();
  check(!document.querySelector('[role="dialog"]') && events.size === 0 && document.activeElement.id === "open", "Escape closes, unsubscribes and restores focus");
  mode = "normal"; return { stale: true, pagination: true, source: true, approval: true, focus: true };
};
window.historyLayoutProbe = async (theme) => {
  document.documentElement.dataset.theme = theme;
  document.getElementById("open").focus(); click("#open"); await tick();
  const dialog = document.querySelector(".delegation-history"), body = document.querySelector(".delegation-history-body");
  const rect = dialog.getBoundingClientRect();
  check(rect.left >= 0 && rect.right <= innerWidth && rect.top >= 0 && rect.bottom <= innerHeight, "Dialog must fit viewport");
  check(body.scrollWidth <= body.clientWidth + 1, "Dialog content must not overflow horizontally");
  const background = getComputedStyle(dialog).backgroundColor;
  dialog.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); await tick();
  return background;
};
window.fixtureReady = true;
